#include <bits/stdc++.h>
using namespace std;

int main(){
    int n;
    scanf("%d",&n);
    vector<int> p(n);
    for(int i=0;i<n;i++) scanf("%d",&p[i]);

    vector<pair<int,int>> ops;

    auto apply_op = [&](int x, int y){
        // [prefix x | middle | suffix y] -> [suffix | middle | prefix]
        vector<int> np;
        for(int i=n-y;i<n;i++) np.push_back(p[i]);
        for(int i=x;i<n-y;i++) np.push_back(p[i]);
        for(int i=0;i<x;i++) np.push_back(p[i]);
        p = np;
        ops.push_back({x,y});
    };

    for(int placed=0; placed<n-2; placed++){
        // Find where (placed+1) is
        int pos=-1;
        for(int i=placed;i<n;i++) if(p[i]==placed+1){pos=i;break;}
        if(pos==placed) continue;

        // Step 1: bring element to position n-1
        if(pos != n-1){
            // We want to move p[pos] to position n-1
            // Use x=pos+1, y=n-1-pos
            // x+y = pos+1+n-1-pos = n, need x+y < n, so this doesn't work
            // Instead: use x=pos+1, y=n-pos-2 (one less suffix)
            // Then element at pos goes to: it's at position pos in original = last of prefix
            // New array: [suffix of size n-pos-2] + [middle of size 1 = p[pos]] + [prefix of size pos+1]
            // Wait no, middle is p[x..n-y-1] = p[pos+1..pos+1] = {p[pos+1]}... no
            // middle = p[pos+1 .. n-(n-pos-2)-1] = p[pos+1..pos+1] only if n-pos-2 leaves one middle
            // Actually middle = p[x .. n-y-1] = p[pos+1 .. pos+1]. That's size 1.
            // New: suffix(n-pos-2 elems from end) + middle(1 elem) + prefix(pos+1 elems from start)
            // Element at pos is in prefix (last element of prefix), goes to end position n-1. 

            int x = pos+1, y = n-pos-2;
            if(y > 0 && x > 0 && x+y < n){
                apply_op(x, y);
            } else {
                // y=0 means pos=n-2. Use x=1, y=1 to do a small rotation, then retry
                // Actually if pos=n-2: x=n-1, y=0 invalid. Use op x=n-2, y=1: brings last elem to front, prefix of n-2 to end. Element was at n-2, now at position n-1.
                // x=n-2,y=1: x+y=n-1<n. Good if n>=3.
                if(pos==n-2){
                    apply_op(pos, 1); // x=n-2, y=1
                    // element was at pos=n-2, it's in prefix[0..n-3], last position of prefix -> goes to position n-1
                }
            }
        }
        // Now element should be at n-1
        // Step 2: bring from n-1 to position placed using x=placed+1, y=1 (if valid)
        if(p[placed]==placed+1) continue;
        int x2 = placed+1, y2 = 1;
        if(x2>0 && y2>0 && x2+y2<n){
            apply_op(x2, y2);
        }
    }

    printf("%d\n",(int)ops.size());
    for(auto&[x,y]:ops) printf("%d %d\n",x,y);
}
